{"code":"import os, json

skills_dir = os.path.expanduser("~/.hermes/skills")
hermes_home = os.path.expanduser("~/.hermes")

# Collect all skill names (directory names containing SKILL.md)
all_skills = {}
for root, dirs, files in os.walk(skills_dir):
    if 'SKILL.md' in files:
        rel = os.path.relpath(root, skills_dir)
        all_skills[rel] = root

# Find references in cron jobs
cron_refs = set()
jobs_file = os.path.join(hermes_home, "cron/jobs.json")
if os.path.exists(jobs_file):
    with open(jobs_file) as f:
        jobs = json.load(f)
    if isinstance(jobs, list):
        for j in jobs:
            if isinstance(j, dict):
                for s in j.get('skills', []) or []:
                    cron_refs.add(s)

# Find references in SKILL.md files themselves (cross-references)
skill_self_refs = set()
for name, path in all_skills.items():
    skmd = os.path.join(path, "SKILL.md")
    if os.path.exists(skmd):
        with open(skmd) as f:
            content = f.read()
        for other in all_skills:
            short = other.split('/')[-1]
            if short in content and other != name:
                skill_self_refs.add(other)

# ALL referenced skills (by name stem)
ref_stems = set()
for r in cron_refs:
    ref_stems.add(r)

# Find UNREFERENCED skills — those whose name stem doesn't appear anywhere
# Also check root-level skills separately
unreferenced = []
for name in all_skills:
    short = name.split('/')[-1]
    if short not in ref_stems and name not in skill_self_refs:
        # Check if it's a variant: root skills that have pua/codex/etc copies are fine
        is_dup_variant = False
        for other in all_skills:
            if other != name and other.split('/')[-1] == short:
                is_dup_variant = True
                break
        # Root-level standalone skills with no refs are candidates
        if '/' not in name and not is_dup_variant:
            if short not in ref_stems:
                unreferenced.append(name)

print(f"Total skills: {len(all_skills)}")
print(f"Cron-skills refs: {len(cron_refs)}")
print(f"Cross-refs in SKILL.md: {len(skill_self_refs)}")
print(f"\n=== Standalone root skills with NO references ({len(unreferenced)}) ===")
for s in sorted(unreferenced):
    print(f"  {s}")

# Also find empty/stub skills
print("\n=== Empty/stub skills (< 200 bytes SKILL.md) ===")
for name, path in sorted(all_skills.items()):
    skmd = os.path.join(path, "SKILL.md")
    if os.path.exists(skmd):
        size = os.path.getsize(skmd)
        if size < 200:
            print(f"  {name} ({size}B)")
